 void night(){if(!ScrollService.connected){Toast.makeText(this,"Activez le service d’accessibilité",Toast.LENGTH_LONG).show();return;}TimePickerDialog picker=new TimePickerDialog(this,(v,hour,minute)->{java.util.Calendar c=java.util.Calendar.getInstance();c.set(java.util.Calendar.HOUR_OF_DAY,hour);c.set(java.util.Calendar.MINUTE,minute);c.set(java.util.Calendar.SECOND,0);c.set(java.util.Calendar.MILLISECOND,0);if(c.getTimeInMillis()<=System.currentTimeMillis())c.add(java.util.Calendar.DAY_OF_YEAR,1);nightAt=c.getTimeInMillis();p.edit().putInt("nightHour",hour).putInt("nightMinute",minute).apply();new AlertDialog.Builder(this).setTitle("Armer le mode nocturne").setMessage("Laissez le téléphone en charge, déverrouillé, sur les résultats Ricardo. Autorisez la capture maintenant. Une seule session sera lancée à "+String.format(java.util.Locale.US,"%02d:%02d",hour,minute)+".").setNegativeButton("Annuler",(d,k)->{if(getIntent().getBooleanExtra("nightFromRicardo",false))finish();}).setOnCancelListener(d->{if(getIntent().getBooleanExtra("nightFromRicardo",false))finish();}).setPositiveButton("Armer",(d,k)->{if(RecordingService.instance!=null)RecordingService.instance.finishCapture();startActivityForResult(getSystemService(MediaProjectionManager.class).createScreenCaptureIntent(),42);}).show();},p.getInt("nightHour",3),p.getInt("nightMinute",0),true); picker.setOnCancelListener(d->{if(getIntent().getBooleanExtra("nightFromRicardo",false))finish();});picker.show();}
