 void copyPrompt(){((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Prompt Ricardo",SessionReport.prompt(this)));Toast.makeText(this,"Prompt copié",Toast.LENGTH_SHORT).show();} void shareBatch(){org.json.JSONArray a=SessionReport.clips(this);java.util.ArrayList<Uri> uris=new java.util.ArrayList<>();int missing=0;for(int j=0;j<a.length();j++){org.json.JSONObject o=a.optJSONObject(j);if(o==null)continue;Uri u=Uri.parse(o.optString("uri"));try(android.os.ParcelFileDescriptor f=getContentResolver().openFileDescriptor(u,"r")){if(f!=null)uris.add(u);else missing++;}catch(Exception e){missing++;}}if(uris.isEmpty()){Toast.makeText(this,"Aucune vidéo disponible dans la dernière session",Toast.LENGTH_LONG).show();return;}String prompt=SessionReport.prompt(this);if(missing>0)prompt+="\\nAttention : "+missing+" vidéo(s) supprimée(s) ou inaccessible(s).";final String message=prompt;Intent i=new Intent(Intent.ACTION_SEND_MULTIPLE).setType("video/mp4").putParcelableArrayListExtra(Intent.EXTRA_STREAM,uris).putExtra(Intent.EXTRA_TEXT,message).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);ClipData clip=ClipData.newRawUri("Vidéos Ricardo",uris.get(0));for(int j=1;j<uris.size();j++)clip.addItem(new ClipData.Item(uris.get(j)));i.setClipData(clip);((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Prompt Ricardo",message));i.setPackage("com.openai.chatgpt");try{startActivity(i);}catch(ActivityNotFoundException e){i.setPackage(null);startActivity(Intent.createChooser(i,"Partager les vidéos (prompt copié)"));}} void shareLast(){String value=p.getString("lastVideo","");if(value.isEmpty()){Toast.makeText(this,"Aucune vidéo",Toast.LENGTH_SHORT).show();return;}Uri u=Uri.parse(value);Intent i=new Intent(Intent.ACTION_SEND).setType("video/mp4").putExtra(Intent.EXTRA_STREAM,u).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("Vidéo Ricardo",u));startActivity(Intent.createChooser(i,"Partager la vidéo"));}
 void videos(){java.util.ArrayList<Uri> uris=new java.util.ArrayList<>();java.util.ArrayList<String> names=new java.util.ArrayList<>();try(Cursor c=getContentResolver().query(MediaStore.Downloads.EXTERNAL_CONTENT_URI,new String[]{"_id","_display_name"},"relative_path LIKE ? AND is_pending=0",new String[]{"Download/Ricardo AutoScroll%"}, "date_added DESC")){while(c!=null&&c.moveToNext()){uris.add(ContentUris.withAppendedId(MediaStore.Downloads.EXTERNAL_CONTENT_URI,c.getLong(0)));names.add(c.getString(1));}}catch(Exception e){Toast.makeText(this,"Lecture indisponible",Toast.LENGTH_SHORT).show();}new AlertDialog.Builder(this).setTitle("Mes enregistrements").setItems(names.toArray(new String[0]),(d,i)->{Uri u=uris.get(i);new AlertDialog.Builder(this).setTitle(names.get(i)).setItems(new String[]{"Visionner","Partager","Supprimer"},(a,k)->{if(k==2){new AlertDialog.Builder(this).setMessage("Supprimer cette vidéo ?").setNegativeButton("Annuler",null).setPositiveButton("Supprimer",(x,y)->{try{getContentResolver().delete(u,null,null);}catch(Exception e){Toast.makeText(this,"Suppression impossible",Toast.LENGTH_SHORT).show();}}).show();}else{Intent in=new Intent(k==0?Intent.ACTION_VIEW:Intent.ACTION_SEND);if(k==0)in.setDataAndType(u,"video/mp4");else in.setType("video/mp4").putExtra(Intent.EXTRA_STREAM,u);in.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(Intent.createChooser(in,null));}catch(ActivityNotFoundException e){Toast.makeText(this,"Aucune application compatible",Toast.LENGTH_SHORT).show();}}}).show();}).setPositiveButton("Fermer",null).show();}
